import{_ as o,o as t,c as a,a5 as l}from"./chunks/framework.BPFk9-tb.js";const k=JSON.parse('{"title":"写作课作业-085","description":"","frontmatter":{"date":"2020-10-22T19:37:31","title":"写作课作业-085","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/085.md","filePath":"posts/homework/085.md"}'),p={name:"posts/homework/085.md"};function r(c,e,s,i,n,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<blockquote><p>《微信互联网平民创业》之《17.有哪些事情就是绝对不能做?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>无论你在卖什么课，卖什么货，或者卖什么服务，实际上，你都要把自己卖出去才行。</p></blockquote><blockquote><p>我现在还没有产品、甚至暂时还没有服务、我更没有品牌……那么，我必须投入时间和精力打造自己的「口碑」！</p></blockquote><blockquote><p>「打造更好的自己」是「平民创业」的最核心内容：必须剔除讨好型人格，新成为不令人讨厌的人，再成为受人欢迎的人……为了持续打造长期维护良好的「口碑」，或称为「个人品牌」。</p></blockquote><blockquote><p>绝不能做的事情：</p><p>不要假人设，坚决不占任何便宜。</p><p>不要冷家人，家人是我们唯一天然必须照顾的人——这是唯一理所当然的责任。</p><p>不要乱帮人，每天腾出一点精力真诚的在自己能力范围帮助他人，但轻易不要用钱帮人！</p><p>不要瞎站队，治疗「讨好型人格」的方子非常简单：有正事儿可做！</p><p>不要惹众怒，这是生计问题，而且还是非常长期的生计问题！</p></blockquote><blockquote><p>「这世界不好」本身没有什么不好。</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>坚决不要占小便宜。因为一次合作中，没有完全的公平交易，自己就没了第二次合作。自己想着要长期，却做着不是长期的事，想想多可怕。</p><p>人就是这样，被照顾的时候都是巨婴，只有开始照顾别人的时候才会「突然成熟」。自己身边有这样的例子，包括自己也是，被妻子照顾得好好的，但本事没长进，脾气倒长了。看到这段文字确认需要好好反思。因为也看过一些会照顾人的朋友，不仅事业很顺利，家庭也能照顾得好好的，就好像他们的时间特别充足一样。</p>',10)])])}const d=o(p,[["render",r]]);export{k as __pageData,d as default};
